import React, {useRef, useState, useEffect} from "react";
import axios from "axios";
import WordButton from "./components/WordButton";
import "../styles/English.css";
import Header from "./components/Header";

const English = () => {
	const [data, setData] = useState(null);
	const [loading, setLoading] = useState(true);
	const [error, setError] = useState(null);
	const [answerList, setAnswerList] = useState(["a"]);
	const putAnswer = (value) => {
		setAnswerList((prevItem) => {
			const newItem = prevItem.includes(value)
				? prevItem.filter((i) => i !== value) // 제거
				: [...prevItem, value]; // 추가

			console.log("즉시 변경된 리스트:", prevItem);
			return newItem;
		});
	};
	const putA = () => {
		setAnswerList(() => {
			return [...answerList, "a"];
		});
	};

	useEffect(() => {
		console.log("렌더링 후 현재 리스트:", answerList);
	}, [answerList]);

	useEffect(() => {
		// 데이터 요청
		const fetchData = async () => {
			try {
				const response = await axios.get(
					"http://localhost:8080/api/v1/eng/1"
				);
				setData(response.data); // 서버에서 받은 데이터 저장
				setLoading(false);
			} catch (err) {
				setError(err.message);
				setLoading(false);
			}
		};

		fetchData();
	}, []); // 빈 배열로 설정하면 컴포넌트가 마운트될 때만 실행

	if (loading) return <p>Loading...</p>;
	if (error) return <p>Error: {error}</p>;

	return (
		<div className="quiz-container">
			<div className="quiz-sentence">
				<p>{data.korSen}</p>

				<button type="button" onClick={() => putAnswer()}>
					A
				</button>
				{data.engSenList.map((value, index) => (
					<WordButton
						size="large"
						key={index}
						label={value}
						// isActive={answerList.includes(index)}
						onClick={putAnswer}
					/>
				))}
				<ul>
					{answerList.map((value, index) => (
						<li key={index}>{value}</li>
					))}
				</ul>
			</div>
		</div>
	);
};
export default English;
